create function pg_temp.bundle() returns jsonb language sql as $$select jsonb_set(jsonb_set(jsonb_set(jsonb_set(pg_temp.base_bundle(),'{questions,3,student,kind}','"open_ended"'),'{questions,3,student,choices}','[]'),'{questions,3,teacher,correct_key}','null'),'{package_key}','"test-credit-safety"');$$;
create function pg_temp.as_admin() returns void language sql as $$select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009801","role":"authenticated","gina":{"admin":true}}',true)$$;
create function pg_temp.as_parent1() returns void language sql as $$select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009802","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000009801","role":"parent"}}',true)$$;
create function pg_temp.as_parent2() returns void language sql as $$select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009803","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000009802","role":"parent"}}',true)$$;
create function pg_temp.as_child() returns void language sql as $$select set_config('request.jwt.claims','{"sub":"00000000-0000-4000-8000-000000009804","role":"authenticated","gina":{"family_id":"10000000-0000-4000-8000-000000009801","role":"child"}}',true)$$;
create function pg_temp.as_service() returns void language sql as $$select set_config('request.jwt.claims','{"role":"service_role"}',true)$$;
create function pg_temp.item(kind text,id uuid) returns jsonb language sql as $$select value from jsonb_array_elements(public.admin_library_content_items(kind,null,500)) where value->>'id'=id::text$$;

-- 1. Lifecycle view: draft → reviewed → approved → published; approval is not publication -------------
set local role authenticated;select pg_temp.as_admin();
insert into state select 'rev1',(public.admin_import_library_bundle(gen_random_uuid(),pg_temp.bundle())->>'id')::uuid;
select is(pg_temp.item('package',pg_temp.id('rev1'))->>'status','draft','imported package is a draft');
select is(pg_temp.item('package',pg_temp.id('rev1'))->>'live','false','draft is not live');
select public.admin_review_library_question(gen_random_uuid(),pg_temp.id('rev1'),'question-1',1,0,'changes_requested','Stem needs a unit');
select is(pg_temp.item('package',pg_temp.id('rev1'))->>'status','reviewed','first editorial decision moves the package to reviewed');
select is(pg_temp.item('package',pg_temp.id('rev1'))->>'admin_decision','changes_requested','open change request surfaces as the admin decision');
select public.admin_review_library_question(gen_random_uuid(),pg_temp.id('rev1'),'question-1',1,1,'suitable','Fixed in review');
select public.admin_review_library_question(gen_random_uuid(),pg_temp.id('rev1'),'question-2',1,0,'suitable','ok');
select public.admin_review_library_question(gen_random_uuid(),pg_temp.id('rev1'),'question-3',1,0,'suitable','ok');
select public.admin_review_library_question(gen_random_uuid(),pg_temp.id('rev1'),'question-4',1,0,'suitable','ok');
select is(pg_temp.item('package',pg_temp.id('rev1'))->>'status','approved','all suitable = approved');
select is(pg_temp.item('package',pg_temp.id('rev1'))->>'live','false','approved package is still not served');
select pg_temp.as_parent1();
select is(jsonb_array_length(public.get_published_library_packages(5,'Matematik')),0,'approval does not publish to families');
select throws_ok($$select public.admin_library_content_items()$$,'42501','forbidden','parent cannot read the admin lifecycle list');
reset role;select pg_temp.as_service();
select public.prepare_library_delivery_media('00000000-0000-4000-8000-000000009801',pg_temp.id('rev1'),jsonb_build_array(jsonb_build_object('source_hash',pg_temp.bundle()#>>'{assets,0,sha256}','base64',pg_temp.bundle()#>>'{assets,0,base64}')));
set local role authenticated;select pg_temp.as_admin();
select throws_ok($$select public.admin_library_content_items('bogus')$$,'P0001','invalid_input','unknown kind rejected');
select public.admin_set_library_publication(gen_random_uuid(),pg_temp.id('rev1'),0,public.admin_library_publication(pg_temp.id('rev1'))#>>'{checks,review_fingerprint}','Credit test package','Test',array['free']::public.plan_code[],'Test curriculum',true,'published');
select is(pg_temp.item('package',pg_temp.id('rev1'))->>'status','published','publication decision = published');
select is(pg_temp.item('package',pg_temp.id('rev1'))->>'live','true','published, review-current, media-complete package is live');
select is(pg_temp.item('package',pg_temp.id('rev1'))->>'publication_version','1','publication version exposed');
-- A new draft revision never touches the live revision.
insert into state select 'rev2',(public.admin_import_library_bundle(gen_random_uuid(),
 jsonb_set(jsonb_set(jsonb_set(jsonb_set(pg_temp.bundle(),'{revision}','2'),'{previous_hash}',to_jsonb(pg_temp.q($$select content_hash from gina.library_import_packages where id='$$||pg_temp.id('rev1')||$$'$$))),'{questions,0,student,stem}','"Düzeltilmiş soru kökü: AB ve CD için uygun adı seç."'),'{questions,0,revision}','2'))->>'id')::uuid;
select is(pg_temp.item('package',pg_temp.id('rev2'))->>'status','draft','revision 2 starts as a draft');
select is(pg_temp.item('package',pg_temp.id('rev1'))->>'status','published','revision 1 stays published');
select is(pg_temp.item('package',pg_temp.id('rev2'))->>'previous_id',pg_temp.id('rev1')::text,'revision chain recorded');
select pg_temp.as_parent1();
select is(public.get_published_library_packages(5,'Matematik')#>>'{0,id}',pg_temp.id('rev1')::text,'families still see only the published revision');
select is(jsonb_array_length(public.get_published_library_packages(5,'Matematik')),1,'draft revision is not served');
select pg_temp.as_admin();
select is(jsonb_array_length(public.admin_library_package_trail(pg_temp.id('rev2'))->'revisions'),2,'package trail walks both revisions');
select is(public.admin_library_package_trail(pg_temp.id('rev2'))#>>'{revisions,0,questions,0,outcome}','suitable','trail carries latest per-question outcome');
select is(public.admin_library_package_trail(pg_temp.id('rev2'))#>>'{revisions,1,status}','draft','trail shows revision 2 unreviewed');
select pg_temp.as_parent1();
select throws_ok($$select public.admin_library_package_trail(pg_temp.id('rev1'))$$,'42501','forbidden','parent cannot read the package trail');
reset role;
savepoint withdrawn;
set local role authenticated;select pg_temp.as_admin();
select public.admin_set_library_publication(gen_random_uuid(),pg_temp.id('rev1'),1,public.admin_library_publication(pg_temp.id('rev1'))#>>'{checks,review_fingerprint}','Credit test package','Test',array['free']::public.plan_code[],'Test curriculum',true,'archived','Synthetic archive');
select is(pg_temp.item('package',pg_temp.id('rev1'))->>'status','withdrawn','archived publication = withdrawn');
rollback to withdrawn;
-- Published/assigned versions are immutable at the table level too.
select throws_ok($$update gina.library_publications set version=version+5 where package_id=pg_temp.id('rev1')$$,'P0001','library_publication_immutable','publication version cannot jump');
select throws_ok($$delete from gina.library_publications where package_id=pg_temp.id('rev1')$$,'P0001','library_publication_immutable','publication row cannot be deleted');
insert into public.library_collections(id,title,grade,subject,status,plans) values('70000000-0000-4000-8000-000000009801','Legacy',5,'Matematik','published',array['free']::public.plan_code[]);
insert into public.library_items(id,collection_id,content,content_hash,status) values('70000000-0000-4000-8000-000000009802','70000000-0000-4000-8000-000000009801','{"grade":5,"subject":"Matematik","topic":"Legacy","kind":"open_ended","stem":"Eski soru"}','legacyhash-1','draft');
update public.library_items set content=content||'{"topic":"Legacy edited"}' where id='70000000-0000-4000-8000-000000009802';
select is((select content->>'topic' from public.library_items where id='70000000-0000-4000-8000-000000009802'),'Legacy edited','draft legacy item is editable');
update public.library_items set status='published' where id='70000000-0000-4000-8000-000000009802';
select throws_ok($$update public.library_items set content=content||'{"topic":"Changed live"}' where id='70000000-0000-4000-8000-000000009802'$$,'P0001','library_item_immutable','published legacy item content frozen');
select lives_ok($$update public.library_items set status='archived' where id='70000000-0000-4000-8000-000000009802'$$,'status change (archive) still allowed');
select is((select count(*) from gina.library_content_items where kind in('legacy_item','collection','legacy_contribution','contribution_set','package')),4::bigint,'view unifies two package revisions, one legacy item and one collection (no contributions yet)');

-- 2. Credits: same acquisition never charges twice --------------------------------------------
set local role authenticated;select pg_temp.as_parent1();
select is(public.family_library_credits()#>>'{monthly,limit}','3','monthly allowance read from plan');
select is(public.family_library_credits()#>>'{monthly,used}','0','nothing used yet');
select is(public.family_library_credits()->>'total_remaining','3','total remaining = monthly + bonus');
select ok((public.family_library_credits()#>>'{monthly,renews_at}')::timestamptz>(public.family_library_credits()#>>'{monthly,period_start}')::timestamptz,'renewal is after period start');
select throws_ok($$select public.family_library_credits('10000000-0000-4000-8000-000000009802')$$,'42501','forbidden','parent cannot read another family''s credits');
insert into state values('req1',gen_random_uuid());
select is((public.acquire_library_units(pg_temp.id('req1'),pg_temp.id('rev1'),1,array['source:segments'])->>'charged'),'3','shared source acquired as one unit of 3 questions');
select is((public.acquire_library_units(pg_temp.id('req1'),pg_temp.id('rev1'),1,array['source:segments'])->>'charged'),'3','same request replays the receipt');
select is(public.family_library_credits()#>>'{monthly,used}','3','replay did not charge again');
select is((public.acquire_library_units(gen_random_uuid(),pg_temp.id('rev1'),1,array['source:segments'])->>'charged'),'0','new request for an owned unit charges nothing');
select is(public.family_library_credits()#>>'{monthly,used}','3','owned unit stays at 3');
