select is(public.group_exam_phases('60000000-0000-4000-8000-000000009802')#>>'{review,phase}','in_review','unreadable answer still counts as pending');
select pg_temp.as_parent1();
select is(public.get_group_result('60000000-0000-4000-8000-000000009802','20000000-0000-4000-8000-000000009801')->>'ranking_reason','unreadable','unreadable is reported, not scored as zero');
rollback to unreadable;
set local role authenticated;select pg_temp.as_admin();
select public.admin_save_cohort_review(gen_random_uuid(),pg_temp.id('entry3'),4,0,pg_temp.detail()#>>'{questions,3,answer_hash}','{"c1":1,"c2":1,"c3":0,"c4":0}','scored','İki ölçüt karşılandı, gerekçe yeterli.');
select is(public.group_exam_phases('60000000-0000-4000-8000-000000009802')#>>'{review,phase}','ready_to_publish','reviewed but unpublished');
select pg_temp.as_parent1();
select is(public.get_group_result('60000000-0000-4000-8000-000000009802','20000000-0000-4000-8000-000000009801')->>'ranked','false','reviewed but unpublished result is not ranked');
select is(public.get_group_result('60000000-0000-4000-8000-000000009802','20000000-0000-4000-8000-000000009801')->>'ranking_reason','results_not_published','reason: not published');
select pg_temp.as_admin();
select public.admin_publish_cohort_results(gen_random_uuid(),'60000000-0000-4000-8000-000000009802',public.admin_cohort_review_queue('60000000-0000-4000-8000-000000009802')#>>'{state,fingerprint}',(public.admin_cohort_review_queue('60000000-0000-4000-8000-000000009802')#>>'{state,version}')::int);
select pg_temp.as_parent1();
select is(public.get_group_result('60000000-0000-4000-8000-000000009802','20000000-0000-4000-8000-000000009801')->>'ranked','true','published, scored, consented entry is ranked');
select ok((public.get_group_result('60000000-0000-4000-8000-000000009802','20000000-0000-4000-8000-000000009801')#>>'{ranking,0,points}')::int between 2 and 5 and (public.get_group_result('60000000-0000-4000-8000-000000009802','20000000-0000-4000-8000-000000009801')#>>'{ranking,0,mine}')='true','board shows the reviewed total for the family');
select is(public.group_exam_phases('60000000-0000-4000-8000-000000009802')#>>'{review,phase}','published','review phase published');
select public.set_group_ranking_consent('60000000-0000-4000-8000-000000009802','20000000-0000-4000-8000-000000009801',false);
select is(public.get_group_result('60000000-0000-4000-8000-000000009802','20000000-0000-4000-8000-000000009801')->>'ranked','false','ranking consent withdrawn = not ranked');
select is(public.get_group_result('60000000-0000-4000-8000-000000009802','20000000-0000-4000-8000-000000009801')->>'ranking_reason','no_consent','reason: no consent');
select ok((public.get_group_result('60000000-0000-4000-8000-000000009802','20000000-0000-4000-8000-000000009801')->>'points')::int between 2 and 5,'own points remain visible without ranking');
select pg_temp.as_admin();
select throws_ok($$select public.get_group_result('60000000-0000-4000-8000-000000009802','20000000-0000-4000-8000-000000009801')$$,'42501','forbidden','admin without a parent session cannot read a family result');
select is(public.group_exam_phases('60000000-0000-4000-8000-000000009802')#>>'{participation,entries}','1','admin phases include the entry count');
reset role;
select * from finish();rollback;
